import{_ as o,H as n,f as a,i as t}from"./chunks/framework.CSxcEb-0.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),r={name:"troubleshooting.md"};function l(i,e,s,d,c,u){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="google-calendar-401-403-or-missing-calendars" tabindex="-1">Google Calendar 401 / 403 or missing calendars <a class="header-anchor" href="#google-calendar-401-403-or-missing-calendars" aria-label="Permalink to &quot;Google Calendar 401 / 403 or missing calendars&quot;">​</a></h2><ol><li>Enable the <a href="https://console.cloud.google.com/apis/library/calendar-json.googleapis.com" target="_blank" rel="noreferrer">Google Calendar API</a> on your Google Cloud project linked to Firebase.</li><li>In TemPad: <strong>Settings → Google Calendar sync → Connect calendars</strong> and approve all requested permissions.</li><li>If you previously connected before the API was enabled, disconnect/reconnect to refresh the token.</li></ol><h2 id="no-writable-calendar-for-export" tabindex="-1">No writable calendar for export <a class="header-anchor" href="#no-writable-calendar-for-export" aria-label="Permalink to &quot;No writable calendar for export&quot;">​</a></h2><ul><li>Pick a Google calendar you own or can edit</li><li>Reconnect calendars and confirm write permission in the Google consent screen</li></ul><h2 id="sync-not-running" tabindex="-1">Sync not running <a class="header-anchor" href="#sync-not-running" aria-label="Permalink to &quot;Sync not running&quot;">​</a></h2><ul><li>You must be signed in (not local-only)</li><li>Enable at least one calendar in Settings</li><li>Keep the tab open or return to it — use <strong>Sync now</strong> to force a pull</li></ul><h2 id="changes-not-on-other-devices" tabindex="-1">Changes not on other devices <a class="header-anchor" href="#changes-not-on-other-devices" aria-label="Permalink to &quot;Changes not on other devices&quot;">​</a></h2><ul><li>Confirm <strong>Google sign-in</strong> (cloud sync), not <strong>Continue without sign-in</strong></li><li>Check Firestore rules are deployed from <code>firestore.rules</code></li><li>Verify Firebase env vars match your project (see README)</li></ul><h2 id="tasks-not-scheduling" tabindex="-1">Tasks not scheduling <a class="header-anchor" href="#tasks-not-scheduling" aria-label="Permalink to &quot;Tasks not scheduling&quot;">​</a></h2><ul><li>Task needs <strong>due date</strong> and <strong>duration</strong></li><li>List’s <strong>scheduling hours</strong> profile must have enabled days with valid start/end</li><li>Press <strong>Reschedule</strong> after bulk edits</li><li>Locked (dragged) blocks stay put until reschedule unlocks them</li></ul><h2 id="sign-in-on-github-pages" tabindex="-1">Sign-in on GitHub Pages <a class="header-anchor" href="#sign-in-on-github-pages" aria-label="Permalink to &quot;Sign-in on GitHub Pages&quot;">​</a></h2><ul><li>Add <code>YOUR_USERNAME.github.io</code> to Firebase authorized domains</li><li>Popup may be replaced by redirect on github.io — wait for redirect to complete</li></ul><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local development&quot;">​</a></h2><ul><li>Use <code>.env.local</code> from <code>.env.example</code> for Firebase</li><li>Without Firebase: <strong>Continue without sign-in</strong> only</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Open an issue on <a href="https://github.com/jaredescott/TemPad" target="_blank" rel="noreferrer">GitHub</a> with browser console errors and whether you use local or signed-in mode.</p>',17)])])}const b=o(r,[["render",l]]);export{g as __pageData,b as default};
